`timescale 1ns / 1ps
//////////////////////////////////////////////////////////////////////////////////
// Engineer: Christian Saliba
//
// Module Name: sha256_vectors_tb
// Description:
// Hashes known single-block SHA-256 vectors through the AXI-Lite interface of
// sha256_axi_lite
// The vectors are from sim/mem/sha256_vectors.mem, generated by
// tools/gen_sha_vectors.py.
// Version: 0.01
//////////////////////////////////////////////////////////////////////////////////

module sha256_vectors_tb;

    localparam int WORDS_PER_VECTOR = 24; // 16 block words + 8 digest words
    localparam int MAX_VECTORS      = 64;
    localparam int POLL_LIMIT       = 500;

    // register offsets, see sha256_reg_if.sv
    localparam logic [7:0] REG_CTRL   = 8'h00;
    localparam logic [7:0] REG_STATUS = 8'h04;
    localparam logic [7:0] REG_BLOCK0 = 8'h08;
    localparam logic [7:0] REG_DIGEST0 = 8'h80;

    logic clk = 1'b0;
    logic aresetn;

    logic [31:0] awaddr;
    logic [2:0]  awprot;
    logic        awvalid;
    logic        awready;

    logic [31:0] wdata;
    logic [3:0]  wstrb;
    logic        wvalid;
    logic        wready;

    logic [1:0]  bresp;
    logic        bvalid;
    logic        bready;

    logic [31:0] araddr;
    logic [2:0]  arprot;
    logic        arvalid;
    logic        arready;

    logic [31:0] rdata;
    logic [1:0]  rresp;
    logic        rvalid;
    logic        rready;

    logic [31:0] vector_mem [0:1 + MAX_VECTORS * WORDS_PER_VECTOR - 1];

    always #5 clk = ~clk;

    sha256_axi_lite dut (
        .s_axi_aclk    (clk),
        .s_axi_aresetn (aresetn),

        .s_axi_awaddr  (awaddr),
        .s_axi_awprot  (awprot),
        .s_axi_awvalid (awvalid),
        .s_axi_awready (awready),

        .s_axi_wdata   (wdata),
        .s_axi_wstrb   (wstrb),
        .s_axi_wvalid  (wvalid),
        .s_axi_wready  (wready),

        .s_axi_bresp   (bresp),
        .s_axi_bvalid  (bvalid),
        .s_axi_bready  (bready),

        .s_axi_araddr  (araddr),
        .s_axi_arprot  (arprot),
        .s_axi_arvalid (arvalid),
        .s_axi_arready (arready),

        .s_axi_rdata   (rdata),
        .s_axi_rresp   (rresp),
        .s_axi_rvalid  (rvalid),
        .s_axi_rready  (rready)
    );


    task automatic axi_write(input logic [7:0] offset, input logic [31:0] data);
        bit aw_done;
        bit w_done;
        begin
            aw_done = 1'b0;
            w_done  = 1'b0;

            @(negedge clk);
            awaddr  = {24'd0, offset};
            awvalid = 1'b1;
            wdata   = data;
            wstrb   = 4'hF;
            wvalid  = 1'b1;
            bready  = 1'b1;
            //handshake
            while (!(aw_done && w_done)) begin
                @(posedge clk);
                if (!aw_done && awvalid && awready) aw_done = 1'b1;
                if (!w_done  && wvalid  && wready)  w_done  = 1'b1;
                @(negedge clk);
                if (aw_done) awvalid = 1'b0;
                if (w_done)  wvalid  = 1'b0;
            end
            //check bresp
            do @(posedge clk); while (!bvalid);
            if (bresp !== 2'b00) begin
                $fatal(1, "FAIL: write to %02h returned bresp=%b", offset, bresp);
            end

            @(negedge clk);
            bready = 1'b0;
        end
    endtask

    task automatic axi_read(input logic [7:0] offset, output logic [31:0] data);
        begin
            @(negedge clk);
            araddr  = {24'd0, offset};
            arvalid = 1'b1;
            rready  = 1'b1;
            //handshake
            do @(posedge clk); while (!arready);
            @(negedge clk);
            arvalid = 1'b0;

            do @(posedge clk); while (!rvalid);
            data = rdata;
            //check rresp
            if (rresp !== 2'b00) begin
                $fatal(1, "FAIL: read of %02h returned rresp=%b", offset, rresp);
            end

            @(negedge clk);
            rready = 1'b0;
        end
    endtask

    int          vector_count;
    int          base;
    int          polls;
    logic [31:0] status;
    logic [31:0] got;
    logic [31:0] expected;
    int          errors;

    initial begin
        #2000000;
        $fatal(1, "FAIL: testbench timed out after 2 ms");
    end

    initial begin
        awaddr  = 32'd0;
        awprot  = 3'd0;
        awvalid = 1'b0;
        wdata   = 32'd0;
        wstrb   = 4'd0;
        wvalid  = 1'b0;
        bready  = 1'b0;
        araddr  = 32'd0;
        arprot  = 3'd0;
        arvalid = 1'b0;
        rready  = 1'b0;
        errors  = 0;
        //clear memory for safety, then load the vectors
        for (int i = 0; i < $size(vector_mem); i++) begin
            vector_mem[i] = 32'hxxxx_xxxx;
        end
        $readmemh("sha256_vectors.mem", vector_mem);

        vector_count = vector_mem[0];
        if (vector_count < 1 || vector_count > MAX_VECTORS) begin
            $fatal(1, "FAIL: bad vector count %0d (is sha256_vectors.mem loaded?)", vector_count);
        end

        aresetn = 1'b0;
        repeat (5) @(posedge clk);
        @(negedge clk);
        aresetn = 1'b1;
        // two reset synchronizer stages, plus margin
        repeat (4) @(posedge clk);

        for (int v = 0; v < vector_count; v++) begin
            base = 1 + v * WORDS_PER_VECTOR;

            axi_read(REG_STATUS, status);
            if (!status[0]) begin
                $fatal(1, "FAIL: vector %0d: core not ready before start (status=%08h)", v, status);
            end

            for (int w = 0; w < 16; w++) begin
                axi_write(REG_BLOCK0 + 8'(w * 4), vector_mem[base + w]);
            end
            axi_write(REG_CTRL, 32'h1);

            polls = 0;
            do begin
                axi_read(REG_STATUS, status);
                polls++;
                if (polls > POLL_LIMIT) begin
                    $fatal(1, "FAIL: vector %0d: done was never set (status=%08h)", v, status);
                end
            end while (!status[2]);

            for (int d = 0; d < 8; d++) begin
                axi_read(REG_DIGEST0 + 8'(d * 4), got);
                expected = vector_mem[base + 16 + d];
                if (got !== expected) begin
                    $display("FAIL: vector %0d DIGEST%0d: expected %08h, got %08h", v, d, expected, got);
                    errors++;
                end
            end

            if (errors == 0) begin
                $display("PASS: vector %0d (%0d status polls)", v, polls);
            end else begin
                $fatal(1, "FAIL: vector %0d digest mismatch", v);
            end
        end

        $display("PASS: all %0d SHA-256 vectors matched", vector_count);
        $finish;
    end

endmodule
